example.code:
notifications {
    notifierSettings = slackNotifier {
        connection = "PROJECT_EXT_4"
        sendTo = "#channel-name"
        messageFormat = simpleMessageFormat()
    }
    buildFailedToStart = true
}

notifications {
    notifierSettings = slackNotifier {
        connection = "PROJECT_EXT_4"
        sendTo = "#channel-name"
        messageFormat = verboseMessageFormat {
            addBranch = true
            addChanges = true
            addStatusText = true
            maximumNumberOfChanges = 15
        }
    }
}

notifications {
    notifierSettings = slackNotifier {
        connection = "PROJECT_EXT_4"
        sendTo = "#channel-name"
        messageFormat = customMessageFormat {
            template = """
                {build.emoji} {build.link} *{build.event}* in branch `{build.branch}`
                Deploying to %env.TARGET%
            """.trimIndent()
            failureTemplate = """
                :rotating_light: {build.link} *failed*, {committers.mentions} please have a look
                {build.status}
                *Failed tests:*
                {tests.failed}
                *Changes:*
                {changes}
            """.trimIndent()
        }
    }
    buildFinishedSuccessfully = true
    buildFailed = true
}
